from decimal import ROUND_HALF_UP, Decimal

from django.db import migrations, models

# The screening's energy figure switched from BMR × activity factor to
# Tannhauser's TER (2026-11-01, the RND resource person's method): BMR +
# physical activity (% of BMR) + TEF (10%), to the nearest 50 kcal. Recompute
# every saved screening from its stored Tannhauser BMR. Same formula as
# clinical.services.calculate_ter_tannhauser (copied: a migration mustn't
# import code that can change later).
ACTIVITY_PCT = {
    "sedentary": Decimal("30"), "lightly_active": Decimal("50"), "moderately_active": Decimal("75"),
    "very_active": Decimal("100"), "extra_active": Decimal("100"),
}


def recompute(apps, schema_editor):
    Screening = apps.get_model("clinical", "PreConsultationScreening")
    for s in Screening.objects.exclude(bmr_kcal=None):
        pa = s.bmr_kcal * ACTIVITY_PCT.get(s.activity_level, ACTIVITY_PCT["sedentary"]) / 100
        ter = (s.bmr_kcal + pa) * Decimal("1.10")
        s.tdee_kcal = (ter / 50).quantize(Decimal("1"), rounding=ROUND_HALF_UP) * 50
        s.save(update_fields=["tdee_kcal"])


